gQG(){return"\u0424\u0430\u0439\u043b\u044b \u0443\u043f\u043e\u0440\u044f\u0434\u043e\u0447\u0435\u043d\u044b \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0434\u043e \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f. \u041a\u0430\u0436\u0434\u044b\u0439 \u0444\u0430\u0439\u043b \u0443\u0434\u0430\u043b\u044f\u0435\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u043d\u0435 \u043f\u043e\u0437\u0434\u043d\u0435\u0435 \u0447\u0435\u043c \u0447\u0435\u0440\u0435\u0437 24 \u0447\u0430\u0441\u0430 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438, \u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0432 \u043f\u044f\u0442\u043d\u0438\u0446\u0443 \u0438 \u0441\u0443\u0431\u0431\u043e\u0442\u0443"},
QN(a){return"\u0416\u0434\u0443\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f ("+a+")"},
gQF(){return"\u041d\u0435\u0442 \u0444\u0430\u0439\u043b\u043e\u0432, \u043e\u0436\u0438\u0434\u0430\u044e\u0449\u0438\u0445 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438"},
QA(a){return"\u0424\u0430\u0439\u043b \u0443\u0436\u0435 \u0443\u0434\u0430\u043b\u0451\u043d \u2013 \u043d\u0443\u0436\u043d\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430 ("+a+")"},
